    T_ext(row_index,col_index) = mom_cons_nT(j);
    U(row_index,col_index) = U_cons_nT(j);
    theta(row_index,col_index) = theta_cons_nT(j);

    col_index = col_index - 1;

end

P_cons = P;
U_cons = U;
theta_cons = theta;
T_cons = T_ext;
T_ela = zeros(7, psize+nsize);
T_act = zeros(7, psize+nsize);
k_ela = zeros(7, psize+nsize-1);
theta_ela = zeros(7, psize+nsize-1);
k_ela_all = [];
theta_ela_all = [];

k_act_poly_result = [];
k_act_error = [];
k_act_error_ratio = [];

minP = 5;
f1 = figure(1);
f1.Position = [500 500 300 200]; 
hold on
grid on
box on
for i = size(P_cons,1)-minP/2.5:-1:1

    P_max = P_cons(i,nsize+1)/1000;
    N_step1 = 1;
    N_step2 = 61;
    N_step1 = (i-1)*1+1;
    N_step2 = psize + nsize + 1 -(i-1)*5;
    
    dU = U_cons(i, N_step1+1:N_step2) - U_cons(i, N_step1:N_step2-1);
    dtheta = theta_cons(i, N_step1+1:N_step2) - theta_cons(i, N_step1:N_step2-1); 

    theta1 = 1/2*(theta_cons(i, N_step1:N_step2-1) + theta_cons(i, N_step1+1:N_step2)); % corresponding to force values
    theta2 = 1/2*(theta1(1:end-1) + theta1(2:end)); % corresponding to stiffness values
    theta1 = theta_cons(i, N_step1:N_step2-1);
    theta2 = theta_cons(i, N_step1:N_step2-2);

    T_ela(i,N_step1:N_step2-1) = dU./dtheta; % no counting for the free-loading part
    T_act(i,N_step1:N_step2-1) = T_ela(i,N_step1:N_step2-1) + 1/2*(T_ext(i, N_step1:N_step2-1) + T_ext(i, N_step1+1:N_step2));

    dT_ela = T_ela(i, N_step1+1:N_step2-1) - T_ela(i, N_step1:N_step2-2);
    dT_act = T_act(i, N_step1+1:N_step2-1) - T_act(i, N_step1:N_step2-2);

    k_ela_all = [k_ela_all dT_ela./(theta1(2:end) - theta1(1:end-1))]; % accumlating with P
    theta_ela_all = [theta_ela_all theta2]; % accumlating with P
    k_ela(i, N_step1:N_step2-2) = dT_ela./(theta1(2:end) - theta1(1:end-1));
    theta_ela(i, N_step1:N_step2-2) = theta2;
    
    k_act = dT_act./(theta1(2:end) - theta1(1:end-1)); % for each P

    k_act_poly = polyval(polyfit(theta2, k_act, 3), theta2); % for each P
    k_act_error = [k_act_error sqrt(mean((k_act - k_act_poly).^2))];
    k_act_error_ratio = [k_act_error_ratio k_act_error(end)/(max(k_act)-min(k_act))];
    
    k_act_poly_result = [k_act_poly_result; polyfit(theta2, k_act, 1)]; % accumlating with P
    if (P_max == 5) || (P_max == 10) || (P_max == 15) 
        color = [0.9290 0.6940 0.1250; 0.8500 0.3250 0.0980; 0 0.4470 0.7410]; % rows for 15, 10, 5kPa
    % plot(theta2, k_act, 'x',  'LineWidth', 1)
    % plot(theta2, k_act_poly, '-', 'LineWidth', 1)
        plot(theta2, k_act, 'x', 'Color', color(1+floor(i/2.5),:), 'LineWidth', 1)
        % plot(theta2, k_act_poly, '-', 'Color', color(1+floor(i/2.5),:), 'LineWidth', 1)
    end
end
xlabel('angle (rad)')
ylabel('stiffness (Nm)')
yticks([-0.018, -0.014, -0.01, -0.006, -0.002])
% xlim([-0.6, 0.8])
xlim([-0.2, 0.5])
ylim([-0.02,0])
fontsize(gcf,13,'points')
% ylim([-400,0])
% legend('k_a: 5kPa', 'k_a: 10kPa', 'k_a: 15kPa')
% legend('k_a: 5kPa', 'k_a: 10kPa', 'k_a: 15kPa', 'k_a: 5kPa (fitted)', 'k_a: 10kPa (fitted)', 'k_a: 15kPa (fitted)')
title('The actuation stiffness vs. angle')

hold off
k_act_error_ratio


